      "heroSummary": "劳特布龙嫩是伯尔尼高地最具代表性的冰川U形谷之一，两侧垂直崖壁间分布着著名的72条瀑布。谷底白色冰川河流、绿色牧场和村庄构成细长纵深，297米高的施陶河瀑布从岩壁凌空落下。米伦和文根分别坐落于山谷两侧高地，拥有截然不同的山谷俯视角度；雪朗峰与 Birg 则提供跨越云层的高山全景。传统木屋与教堂仅作为自然景观构图元素，不单列为世界遗产建筑。坐标包含地图景点、公开摄影位置及交通站点参考锚点。",
